#[test]
fn key_scenarios_match_the_jvm_except_the_registered_findings() {
    let world = World::open(&dir().join("key-diff.dar")).expect("key-diff.dar");
    let expected = tsv("expected.tsv");
    let findings: Vec<String> = tsv("findings.tsv").into_iter().map(|(k, _)| k).collect();
    assert!(!expected.is_empty(), "expected.tsv is empty");

    let (mut matched, mut mismatched) = (0, Vec::new());
    for (name, jvm) in &expected {
        let jvm_norm = strip_party_suffixes(jvm);
        let rust = replay(&world, name)
            .unwrap_or_else(|| panic!("scenario {name} has no Rust replay (add one)"));
        let same = rust == jvm_norm;
        match (same, findings.contains(name)) {
            (true, false) => matched += 1,
            (false, true) => mismatched.push(name.clone()),
            (false, false) => {
                panic!("UNREGISTERED MISMATCH {name}\n  JVM : {jvm_norm}\n  Rust: {rust}")
            }
            (true, true) => {
                panic!("{name} is registered as a finding but now matches: update findings.tsv")
            }
        }
    }
    for f in &findings {
        assert!(
            expected.iter().any(|(n, _)| n == f),
            "finding {f} names no scenario"
        );
    }
    eprintln!(
        "key-diff: {matched} match, {} registered findings: {mismatched:?}",
        mismatched.len()
    );
}
